//! Player scores shared between the match threads of the Pixel Arena server.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

pub type PlayerId = u32;

#[derive(Default)]
struct Inner {
    players: HashMap<PlayerId, i64>,
    total: i64,
}

/// Clones share the same scores, so each match thread keeps its own handle.
/// All state sits behind one lock, so every operation is atomic and no lock
/// ordering (deadlock) problem can arise.
#[derive(Clone, Default)]
pub struct Board {
    inner: Arc<Mutex<Inner>>,
}

impl Board {
    pub fn new() -> Self {
        Self::default()
    }

    fn lock(&self) -> std::sync::MutexGuard<'_, Inner> {
        self.inner.lock().unwrap_or_else(|e| e.into_inner())
    }

    /// Adds a player. Re-joining an id replaces its score; the total follows.
    pub fn join(&self, id: PlayerId, score: i64) {
        let mut g = self.lock();
        let old = g.players.insert(id, score).unwrap_or(0);
        g.total += score - old;
    }

    /// Adds points to a player and to the board total.
    pub fn award(&self, id: PlayerId, points: i64) {
        let mut g = self.lock();
        *g.players.get_mut(&id).expect("unknown player") += points;
        g.total += points;
    }

    /// Moves points between two players. The board total does not change.
    /// Moving points from a player to the same player changes nothing.
    pub fn transfer(&self, from: PlayerId, to: PlayerId, points: i64) {
        let mut g = self.lock();
        assert!(g.players.contains_key(&from) && g.players.contains_key(&to), "unknown player");
        if from == to {
            return;
        }
        *g.players.get_mut(&from).unwrap() -= points;
        *g.players.get_mut(&to).unwrap() += points;
    }

    pub fn score(&self, id: PlayerId) -> i64 {
        self.lock().players[&id]
    }

    pub fn total(&self) -> i64 {
        self.lock().total
    }
}
